import { useMemo, useState, useCallback } from "react";
import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useHighConfidenceIOCs } from "@/hooks/useIndicators";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { GitBranch, Link as LinkIcon, Search, ShieldCheck } from "lucide-react";

type ThreatItem = {
  id: string;
  title: string;
  link: string;
  severity: "critical" | "high" | "medium" | "low";
  category: string;
  source_name: string;
  published_at: string;
  iocs: { cves?: string[]; ipv4?: string[]; sha256?: string[] } | null;
};

type CorrelationGroup = {
  indicator: string;
  indicatorType: "cve" | "ip" | "hash";
  items: ThreatItem[];
  sources: number;
  categories: number;
  score: number;
};

const severityWeight: Record<ThreatItem["severity"], number> = {
  critical: 4,
  high: 3,
  medium: 2,
  low: 1,
};

function getIndicatorList(item: ThreatItem): Array<{ type: CorrelationGroup["indicatorType"]; value: string }> {
  const indicators: Array<{ type: CorrelationGroup["indicatorType"]; value: string }> = [];
  for (const cve of item.iocs?.cves || []) indicators.push({ type: "cve", value: cve });
  for (const ip of item.iocs?.ipv4 || []) indicators.push({ type: "ip", value: ip });
  for (const hash of item.iocs?.sha256 || []) indicators.push({ type: "hash", value: hash });
  return indicators;
}

export default function Correlation() {
  const [search, setSearch] = useState("");
  const [typeFilter, setTypeFilter] = useState<"all" | "cve" | "ip" | "hash">("all");
  const [minLinks, setMinLinks] = useState("2");
  const [expandedGroups, setExpandedGroups] = useState<Set<string>>(new Set());

  // High-confidence IOCs from indicators table (cross-source validated)
  const { data: validatedIOCs = [] } = useHighConfidenceIOCs(200);
  const validatedSet = useMemo(() => new Set(validatedIOCs.map(i => i.value)), [validatedIOCs]);

  const toggleGroup = useCallback((key: string) => {
    setExpandedGroups(prev => {
      const n = new Set(prev);
      n.has(key) ? n.delete(key) : n.add(key);
      return n;
    });
  }, []);

  const { data: items = [], isLoading } = useQuery({
    queryKey: ["correlation-items"],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("threat_items")
        .select("id,title,link,severity,category,source_name,published_at,iocs")
        .order("published_at", { ascending: false })
        .limit(2000);
      if (error) throw error;
      return (data || []) as ThreatItem[];
    },
  });

  const groups = useMemo(() => {
    const map = new Map<string, CorrelationGroup>();

    for (const item of items) {
      const seen = new Set<string>();
      for (const indicator of getIndicatorList(item)) {
        const key = `${indicator.type}:${indicator.value}`;
        if (seen.has(key)) continue;
        seen.add(key);

        const existing = map.get(key);
        if (existing) {
          existing.items.push(item);
        } else {
          map.set(key, {
            indicator: indicator.value,
            indicatorType: indicator.type,
            items: [item],
            sources: 0,
            categories: 0,
            score: 0,
          });
        }
      }
    }

    const minRequired = Number(minLinks) || 2;
    return [...map.values()]
      .map((group) => {
        const uniqueSources = new Set(group.items.map((i) => i.source_name)).size;
        const uniqueCategories = new Set(group.items.map((i) => i.category)).size;
        const severityScore = group.items.reduce((sum, i) => sum + severityWeight[i.severity], 0);
        const score = severityScore + uniqueSources * 2 + uniqueCategories;
        return { ...group, sources: uniqueSources, categories: uniqueCategories, score };
      })
      .filter((group) => group.items.length >= minRequired)
      .filter((group) => (typeFilter === "all" ? true : group.indicatorType === typeFilter))
      .filter((group) => {
        const q = search.trim().toLowerCase();
        if (!q) return true;
        return (
          group.indicator.toLowerCase().includes(q) ||
          group.items.some((i) => i.title.toLowerCase().includes(q) || i.source_name.toLowerCase().includes(q))
        );
      })
      .sort((a, b) => b.score - a.score);
  }, [items, minLinks, search, typeFilter]);

  return (
    <div className="container mx-auto max-w-screen-xl px-4 py-8">
      <div className="mb-6">
        <h1 className="flex items-center gap-3 text-3xl font-bold tracking-tight">
          <GitBranch className="h-8 w-8 text-primary" />
          Threat Correlation Engine
        </h1>
        <p className="mt-1 text-muted-foreground">
          Correlates threats by shared IOCs (CVEs, IPs, hashes) and ranks by cross-source strength.
        </p>
      </div>

      <div className="mb-6 grid gap-3 md:grid-cols-3">
        <div className="relative md:col-span-2">
          <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
          <Input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search indicator, title, source..."
            className="pl-9"
          />
        </div>
        <div className="grid grid-cols-2 gap-3">
          <Select value={typeFilter} onValueChange={(v) => setTypeFilter(v as typeof typeFilter)}>
            <SelectTrigger>
              <SelectValue placeholder="Indicator type" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Types</SelectItem>
              <SelectItem value="cve">CVEs</SelectItem>
              <SelectItem value="ip">IPv4</SelectItem>
              <SelectItem value="hash">SHA256</SelectItem>
            </SelectContent>
          </Select>
          <Select value={minLinks} onValueChange={setMinLinks}>
            <SelectTrigger>
              <SelectValue placeholder="Min links" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="2">2+ Links</SelectItem>
              <SelectItem value="3">3+ Links</SelectItem>
              <SelectItem value="4">4+ Links</SelectItem>
              <SelectItem value="5">5+ Links</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </div>

      <div className="mb-4 grid grid-cols-2 gap-3 md:grid-cols-4">
        <StatCard label="Total Correlations" value={groups.length.toLocaleString()} />
        <StatCard label="IOC-linked Items" value={items.filter((i) => getIndicatorList(i).length > 0).length.toLocaleString()} />
        <StatCard label="Top Correlation Score" value={(groups[0]?.score || 0).toLocaleString()} />
        <StatCard label="Analyzed Threats" value={items.length.toLocaleString()} />
      </div>

      {isLoading ? (
        <div className="py-16 text-center text-muted-foreground">Analyzing correlations...</div>
      ) : groups.length === 0 ? (
        <div className="py-16 text-center text-muted-foreground">No correlated indicators match your filters.</div>
      ) : (
        <div className="space-y-3">
          {groups.slice(0, 120).map((group) => {
            const groupKey = `${group.indicatorType}:${group.indicator}`;
            const isExpanded = expandedGroups.has(groupKey);
            return (
            <Card key={groupKey} className="border-border/60 bg-card/60">
              <CardHeader className="pb-2">
                <div className="flex flex-wrap items-center justify-between gap-2">
                  <CardTitle className="flex items-center gap-2 text-base">
                    <LinkIcon className="h-4 w-4 text-primary" />
                    <span className="font-mono text-sm">{group.indicator}</span>
                  </CardTitle>
                  <div className="flex gap-2 flex-wrap">
                    <Badge variant="secondary">{group.indicatorType.toUpperCase()}</Badge>
                    <Badge variant="outline">Score {group.score}</Badge>
                    <Badge variant="outline">{group.items.length} linked reports</Badge>
                    {validatedSet.has(group.indicator) && (
                      <Badge className="bg-green-500/15 text-green-400 border-green-500/40 text-[9px] gap-1">
                        <ShieldCheck className="h-2.5 w-2.5" /> Multi-source validated
                      </Badge>
                    )}
                  </div>
                </div>
              </CardHeader>
              <CardContent className="space-y-3">
                <div className="text-xs text-muted-foreground">
                  Correlation strength: {group.items.length} reports across {group.sources} sources and {group.categories} categories.
                </div>
                <div className="grid gap-2 md:grid-cols-2">
                  {group.items.slice(0, isExpanded ? undefined : 6).map((item) => (
                    <div key={item.id} className="rounded-md border border-border/50 bg-muted/20 p-2">
                      <div className="mb-1 flex items-center gap-2">
                        <Badge className="text-[10px]">{item.severity.toUpperCase()}</Badge>
                        <Badge variant="outline" className="text-[10px]">{item.source_name}</Badge>
                      </div>
                      <a
                        className="line-clamp-2 text-sm hover:text-primary hover:underline"
                        href={item.link}
                        target="_blank"
                        rel="noopener noreferrer"
                      >
                        {item.title}
                      </a>
                    </div>
                  ))}
                </div>
                {group.items.length > 6 && (
                  <Button variant="ghost" size="sm" className="text-xs" onClick={() => toggleGroup(groupKey)}>
                    {isExpanded ? "Show less" : `+${group.items.length - 6} more linked reports`}
                  </Button>
                )}
              </CardContent>
            </Card>
          );
          })}
        </div>
      )}
    </div>
  );
}

function StatCard({ label, value }: { label: string; value: string }) {
  return (
    <Card className="border-border/60 bg-card/60">
      <CardContent className="p-3">
        <div className="text-xl font-bold text-primary">{value}</div>
        <div className="text-xs text-muted-foreground">{label}</div>
      </CardContent>
    </Card>
  );
}
