import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";

export interface Indicator {
  id: string;
  value: string;
  ioc_type: string;
  first_seen: string;
  last_seen: string;
  sighting_count: number;
  confidence: number;
  reputation: "malicious" | "suspicious" | "clean" | "unknown";
  tags: string[];
  enrichment: Record<string, any>;
  enriched_at: string | null;
  threat_actors: string[];
  malware_families: string[];
  mitre_techniques: string[];
  geo_country: string | null;
  geo_asn: string | null;
  geo_org: string | null;
}

export function useIndicators(opts: {
  type?: string;
  reputation?: string;
  search?: string;
  limit?: number;
} = {}) {
  return useQuery({
    queryKey: ["indicators", opts],
    queryFn: async () => {
      let q = supabase
        .from("indicators")
        .select("*")
        .order("last_seen", { ascending: false })
        .limit(opts.limit ?? 100);

      if (opts.type && opts.type !== "all") q = q.eq("ioc_type", opts.type);
      if (opts.reputation && opts.reputation !== "all") q = q.eq("reputation", opts.reputation);
      if (opts.search) q = q.ilike("value", `%${opts.search}%`);

      const { data, error } = await q;
      if (error) throw error;
      return (data ?? []) as Indicator[];
    },
    staleTime: 5 * 60_000,
  });
}

export function useIOCSightings(value: string | null) {
  return useQuery({
    queryKey: ["ioc_sightings", value],
    queryFn: async () => {
      if (!value) return [];
      const { data, error } = await supabase
        .from("ioc_sightings")
        .select("*, threat_items(id,title,severity,published_at,source_name)")
        .eq("value", value)
        .order("last_seen", { ascending: false });
      if (error) throw error;
      return data ?? [];
    },
    enabled: !!value,
    staleTime: 5 * 60_000,
  });
}

// Cross-source IOCs seen in 3+ sources (highest confidence)
export function useHighConfidenceIOCs(limit = 50) {
  return useQuery({
    queryKey: ["indicators", "high_confidence", limit],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("indicators")
        .select("*")
        .eq("reputation", "malicious")
        .gte("sighting_count", 2)
        .order("sighting_count", { ascending: false })
        .limit(limit);
      if (error) throw error;
      return (data ?? []) as Indicator[];
    },
    staleTime: 5 * 60_000,
  });
}

// Trending IOCs: most sighted in last 24h
export function useTrendingIOCs(limit = 20) {
  return useQuery({
    queryKey: ["indicators", "trending", limit],
    queryFn: async () => {
      const since = new Date(Date.now() - 86400000).toISOString();
      const { data, error } = await supabase
        .from("ioc_sightings")
        .select("value, ioc_type, count:value.count()")
        .gte("last_seen", since)
        .order("count", { ascending: false })
        .limit(limit);
      if (error) throw error;
      return data ?? [];
    },
    staleTime: 5 * 60_000,
    refetchInterval: 5 * 60_000,
  });
}
